async fn send_project_transfer_request_mail(
    repository: &PilotRepository,
    authorization: &persistence::ProjectAuthorizationRecord,
    transfer: &persistence::ProjectTransferRecord,
    sender: &persistence::AppUserRecord,
    public_origin: &str,
    base_path: &str,
) -> Result<(), String> {
    let mut recipients = Vec::new();
    if let Some(user) = repository
        .find_user_by_login_id(&transfer.destination)
        .await
        .map_err(|error| error.to_string())?
    {
        recipients.push(user.email_address);
    } else {
        let members = repository
            .read_organization_members(&transfer.destination)
            .await
            .map_err(|error| error.to_string())?;
        recipients.extend(
            members
                .members
                .into_iter()
                .filter(|member| member.role == "org_admin")
                .map(|member| member.email_address),
        );
    }
    recipients.sort();
    recipients.dedup();

    let accept_url = absolute_app_url(
        public_origin,
        base_path,
        &format!("/project/transfer/{}/{}", transfer.id, transfer.confirm_key),
    );
    let body = format!(
        "Hello {},\n\n@{} wants to transfer the {}/{} project to {}/{}.\n{}\n\n{}\n\nIf you do not accept the transfer it will expire in a day.\n\nThanks",
        transfer.destination,
        authorization.project.owner_name,
        authorization.project.owner_name,
        authorization.project.project_name,
        transfer.destination,
        transfer.new_project_name,
        "To accept the request, visit this link:",
        accept_url,
    );
    let subject = format!(
        "[{}] @{} wants to transfer project",
        authorization.project.project_name, sender.login_id
    );
    for to in recipients.into_iter().filter(|to| !to.trim().is_empty()) {
        let _ = deliver(OutboundMail {
            bcc: Vec::new(),
            body: body.clone(),
            from: default_smtp_from(),
            html: false,
            reply_to: None,
            subject: subject.clone(),
            to,
        });
    }
    Ok(())
}

async fn direct_request_reset_password_email(
    headers: HeaderMap,
    form: HashMap<String, String>,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
    public_origin: String,
    site_name: String,
) -> Response {
    let session = session_manager.ensure_anonymous_session(&headers);
    let redirect_path = match &backend {
        PilotBackend::Repository(repository) => {
            let login_id =
                normalize_identifier(form.get("loginId").map(String::as_str).unwrap_or_default());
            let email_address = normalize_identifier(
                form.get("emailAddress")
                    .map(String::as_str)
                    .unwrap_or_default(),
            );
            match repository
                .find_user_by_login_id(&login_id)
                .await
                .ok()
                .flatten()
            {
                Some(user) if normalize_identifier(&user.email_address) == email_address => {
                    if let Ok(code) = repository
                        .create_password_reset_verification_for_user(user.id, &user.login_id)
                        .await
                    {
                        let _ = send_password_reset_mail(
                            &user.email_address,
                            &code,
                            &public_origin,
                            &base_path,
                            &site_name,
                        );
                    }
                    "/lostPassword?requested=1"
                }
                _ => "/lostPassword?error=invalid",
            }
        }
        _ => "/lostPassword?error=unsupported",
    };

    let mut response = Redirect::to(&base_path_href(&base_path, redirect_path)).into_response();
    for cookie in session_manager.build_set_cookie_headers(&session) {
        response.headers_mut().append(
            axum::http::header::SET_COOKIE,
            cookie.parse().expect("set-cookie header"),
        );
    }
    response
}

async fn direct_reset_password(
    form: HashMap<String, String>,
    backend: PilotBackend,
    base_path: String,
) -> Response {
    let hash_string = form.get("hashString").cloned().unwrap_or_default();
    let password = form.get("password").cloned().unwrap_or_default();
    let retyped_password = form.get("retypedPassword").cloned().unwrap_or_default();

    if password.len() < LEGACY_MIN_PASSWORD_LENGTH || password != retyped_password {
        let query = if hash_string.is_empty() {
            "/resetPassword?error=invalid".to_string()
        } else {
            format!("/resetPassword?error=invalid&s={hash_string}")
        };
        return Redirect::to(&base_path_href(&base_path, &query)).into_response();
    }

    let redirect_path = match &backend {
        PilotBackend::Repository(repository) => {
            match repository
                .find_valid_password_reset_user_id(&hash_string)
                .await
            {
                Ok(Some(user_id)) => match hash(&password, DEFAULT_COST) {
                    Ok(password_hash) => {
                        if repository
                            .update_password_hash_for_user(user_id, &password_hash)
                            .await
                            .is_ok()
                        {
                            let _ = repository
                                .delete_password_reset_verification(&hash_string)
                                .await;
                            "/users/loginform?password=reset".to_string()
                        } else {
                            format!("/resetPassword?error=invalid&s={hash_string}")
                        }
                    }
                    Err(_) => format!("/resetPassword?error=invalid&s={hash_string}"),
                },
                _ => format!("/resetPassword?error=invalid&s={hash_string}"),
            }
        }
        _ => "/resetPassword?error=unsupported".to_string(),
    };

    Redirect::to(&base_path_href(&base_path, &redirect_path)).into_response()
}

#[derive(Deserialize)]
struct DirectUserSidebarQuery {
    hash: Option<String>,
    path: Option<String>,
}

async fn direct_user_sidebar(
    headers: HeaderMap,
    query: DirectUserSidebarQuery,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
) -> Response {
    let session_user_id = session_manager
        .read_session_from_headers(&headers)
        .and_then(|session| session.user_id);
    let iframe_path = legacy_sidebar_iframe_path(&base_path, query);
    let authenticated_sidebar = match (backend, session_user_id) {
        (PilotBackend::Repository(repository), Some(user_id)) => {
            match render_legacy_authenticated_sidebar(&repository, user_id, &base_path).await {
                Ok(sidebar) => Some(sidebar),
                Err(error) => return error.into_response(),
            }
        }
        (PilotBackend::Repository(_), None) => None,
        (PilotBackend::Static, Some(_)) => {
            return RestRouteError::not_implemented("sidebar requires repository backend")
                .into_response();
        }
        (PilotBackend::Static, None) => None,
    };

    (
        [(axum::http::header::CONTENT_TYPE, "text/html; charset=utf-8")],
        render_legacy_user_sidebar_page(&base_path, &iframe_path, authenticated_sidebar.as_deref()),
    )
        .into_response()
}

async fn direct_user_menu_tab_content_list(
    headers: HeaderMap,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
) -> Response {
    let repository = match backend {
        PilotBackend::Repository(repository) => repository,
        PilotBackend::Static => {
            return RestRouteError::not_implemented("usermenu requires repository backend")
                .into_response();
        }
    };
    let Some(session) = session_manager.read_session_from_headers(&headers) else {
        return RestRouteError::from_connect_error(ConnectError::unauthenticated(
            "missing authenticated session",
        ))
        .into_response();
    };
    let actor = match require_authenticated_user(&repository, session.user_id).await {
        Ok(actor) => actor,
        Err(error) => return RestRouteError::from_connect_error(error).into_response(),
    };
    let menu =
        match render_legacy_usermenu_tab_content_for_actor(&repository, &actor, &base_path).await {
            Ok(menu) => menu,
            Err(error) => {
                return error.into_response();
            }
        };

    (
        [(axum::http::header::CONTENT_TYPE, "text/html; charset=utf-8")],
        menu,
    )
        .into_response()
}

async fn render_legacy_authenticated_sidebar(
    repository: &PilotRepository,
    user_id: i64,
    base_path: &str,
) -> Result<String, RestRouteError> {
    let actor = require_authenticated_user(repository, Some(user_id))
        .await
        .map_err(RestRouteError::from_connect_error)?;
    let menu = render_legacy_usermenu_tab_content_for_actor(repository, &actor, base_path).await?;
    Ok(render_legacy_sidebar_inner(base_path, &actor, &menu))
}

async fn render_legacy_usermenu_tab_content_for_actor(
    repository: &PilotRepository,
    actor: &persistence::AppUserRecord,
    base_path: &str,
) -> Result<String, RestRouteError> {
    let recent_projects = repository
        .list_recent_projects_for_user(actor.id)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?;
    let member_projects = repository
        .list_member_projects_for_user(actor.id)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?;
    let recent_issue_records = repository
        .list_recent_workspace_issues_for_user(actor.id, u64::from(WORKSPACE_DAYS_AGO))
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?;
    let recent_issues =
        filter_workspace_issue_items_by_read_acl(repository, actor.id, recent_issue_records)
            .await
            .map_err(RestRouteError::from_connect_error)?;

    Ok(render_legacy_usermenu_tab_content_list(
        base_path,
        &actor.login_id,
        &recent_projects,
        &member_projects,
        &recent_issues,
    ))
}

fn legacy_sidebar_iframe_path(base_path: &str, query: DirectUserSidebarQuery) -> String {
    let path = query
        .path
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("/notifications");
    let mut iframe_path = if path.starts_with('/') {
        base_path_href(base_path, path)
    } else {
        base_path_href(base_path, &format!("/{path}"))
    };
    if let Some(hash) = query
        .hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        iframe_path.push('#');
        iframe_path.push_str(hash.trim_start_matches('#'));
    }
    iframe_path
}

