async fn rest_list_workspace_files(
    headers: HeaderMap,
    query: RestWorkspaceFilesQuery,
    service: PilotServiceImpl,
) -> Result<Json<RestWorkspaceFilesResponse>, RestRouteError> {
    const WORKSPACE_FILES_PAGE_SIZE: u32 = 50;

    let PilotBackend::Repository(repository) = &service.backend else {
        return Err(RestRouteError::not_implemented(
            "workspace files require repository backend",
        ));
    };
    let Some(session) = service.session_manager.read_session_from_headers(&headers) else {
        return Err(RestRouteError::from_connect_error(
            ConnectError::unauthenticated("missing authenticated session"),
        ));
    };
    let actor = require_authenticated_user(repository, session.user_id)
        .await
        .map_err(RestRouteError::from_connect_error)?;
    let page = query.page.or(query.page_num).unwrap_or(1).max(1);
    let filter = query.filter.unwrap_or_default();
    let files = repository
        .list_user_attachments(&actor.login_id, &filter, page, WORKSPACE_FILES_PAGE_SIZE)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?;

    Ok(Json(RestWorkspaceFilesResponse {
        files: files
            .attachments
            .iter()
            .map(|record| rest_workspace_file_item(record, &service.base_path))
            .collect(),
        filter: files.filter,
        page: files.page,
        page_size: files.page_size,
        total: files.total,
        total_pages: files.total_pages,
    }))
}

async fn rest_read_public_user_profile(
    headers: HeaderMap,
    login_id: String,
    query: RestPublicUserProfileQuery,
    service: PilotServiceImpl,
) -> Result<Response, RestRouteError> {
    let PilotBackend::Repository(repository) = &service.backend else {
        return Err(RestRouteError::not_implemented(
            "public user profile requires repository backend",
        ));
    };

    if repository
        .read_organization_by_name(&login_id)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?
        .is_some()
    {
        return Ok(rest_json_response(
            RestPublicUserProfileResponse {
                days_ago: public_profile_days_ago(query.days_ago),
                issue_items: Vec::new(),
                member_projects: Vec::new(),
                profile: None,
                pull_request_items: Vec::new(),
                redirect_path: Some(format!("/organizations/{login_id}")),
                selected: public_profile_selected(query.selected),
                viewer_can_edit_profile: false,
            },
            Context::new(headers),
        ));
    }

    let Some(user) = repository
        .find_user_by_login_id(&login_id)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?
    else {
        return Err(RestRouteError::not_found("user not found"));
    };

    let viewer_id = service
        .session_manager
        .read_session_from_headers(&headers)
        .and_then(|session| session.user_id);
    let viewer_can_edit_profile = viewer_id == Some(user.id);
    let days_ago = public_profile_days_ago(query.days_ago);
    let profile = match repository
        .read_workspace_profile_for_user(user.id)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?
    {
        Some(record) => {
            let avatar_url = workspace_avatar_url(
                repository,
                user.id,
                &record.primary_email_address,
                &service.base_path,
            )
            .await
            .map_err(RestRouteError::from_connect_error)?;
            let mut profile = workspace_profile_from_record(&record, avatar_url);
            if !viewer_can_edit_profile {
                profile.primary_email_address.clear();
            }
            Some(profile)
        }
        None => None,
    };
    let issue_items = filter_workspace_issue_items_by_read_acl_for_viewer(
        repository,
        viewer_id,
        repository
            .list_recent_workspace_issues_for_user(user.id, u64::from(days_ago))
            .await
            .map_err(|error| RestRouteError::internal(error.to_string()))?,
    )
    .await
    .map_err(RestRouteError::from_connect_error)?;
    let pull_request_items = filter_workspace_pull_request_items_by_read_acl_for_viewer(
        repository,
        viewer_id,
        repository
            .list_recent_workspace_pull_requests_for_user(user.id, u64::from(days_ago))
            .await
            .map_err(|error| RestRouteError::internal(error.to_string()))?,
    )
    .await
    .map_err(RestRouteError::from_connect_error)?;
    let member_projects = filter_workspace_member_projects_by_read_acl_for_viewer(
        repository,
        viewer_id,
        repository
            .list_member_projects_for_user(user.id)
            .await
            .map_err(|error| RestRouteError::internal(error.to_string()))?,
    )
    .await
    .map_err(RestRouteError::from_connect_error)?;

    Ok(rest_json_response(
        RestPublicUserProfileResponse {
            days_ago,
            issue_items,
            member_projects,
            profile,
            pull_request_items,
            redirect_path: None,
            selected: public_profile_selected(query.selected),
            viewer_can_edit_profile,
        },
        Context::new(headers),
    ))
}

async fn rest_read_user_statistics(
    headers: HeaderMap,
    login_id: String,
    service: PilotServiceImpl,
) -> Result<Response, RestRouteError> {
    let PilotBackend::Repository(repository) = &service.backend else {
        return Err(RestRouteError::not_implemented(
            "user statistics requires repository backend",
        ));
    };
    let session = require_session(&service.session_manager, &headers)
        .map_err(RestRouteError::from_connect_error)?;
    let _actor = require_authenticated_user(repository, session.user_id)
        .await
        .map_err(RestRouteError::from_connect_error)?;
    let statistics = match repository
        .find_user_by_login_id(&login_id)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?
    {
        Some(user) => repository
            .read_user_statistics(user.id)
            .await
            .map_err(|error| RestRouteError::internal(error.to_string()))?,
        None => persistence::UserStatisticsRecord::default(),
    };

    Ok(rest_json_response(
        rest_user_statistics_from_record(&statistics),
        Context::new(headers),
    ))
}

async fn rest_read_site_users(
    headers: HeaderMap,
    query: RestSiteUsersQuery,
    service: PilotServiceImpl,
) -> Result<Json<RestSiteUserListResponse>, RestRouteError> {
    let repository = rest_require_site_admin_repository(&service, &headers, false).await?;
    let state = rest_site_user_state(query.state)?;
    let record = repository
        .list_site_users(persistence::SiteUserListFilter {
            page: query.page.unwrap_or(1).max(1),
            query: query.query.unwrap_or_default(),
            state,
        })
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?;

    Ok(Json(
        rest_site_user_list_from_record(&repository, &service.base_path, record)
            .await
            .map_err(RestRouteError::from_connect_error)?,
    ))
}

async fn rest_read_site_no_avatar_users(
    headers: HeaderMap,
    service: PilotServiceImpl,
) -> Result<Json<RestSiteNoAvatarUsersResponse>, RestRouteError> {
    let repository = rest_require_site_admin_repository(&service, &headers, false).await?;
    let users = repository
        .list_site_no_avatar_users()
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?;

    Ok(Json(RestSiteNoAvatarUsersResponse {
        users: users
            .into_iter()
            .map(rest_site_no_avatar_user_from_record)
            .collect(),
    }))
}

async fn rest_set_site_user_avatar_from_attachment(
    headers: HeaderMap,
    body: RestSiteAvatarFromAttachmentBody,
    service: PilotServiceImpl,
) -> Result<Json<RestSiteLegacyOkResponse>, RestRouteError> {
    let repository = rest_require_site_admin_repository(&service, &headers, true).await?;
    if body.avatar_file_id <= 0 {
        return Err(RestRouteError::bad_request("avatarFileId is required"));
    }
    if body.email.trim().is_empty() {
        return Err(RestRouteError::bad_request("email is required"));
    }

    match repository
        .set_user_avatar_from_attachment_by_email(&body.email, body.avatar_file_id)
        .await
        .map_err(|error| RestRouteError::internal(error.to_string()))?
    {
        persistence::SiteUserAvatarFromAttachmentResult::Applied
        | persistence::SiteUserAvatarFromAttachmentResult::Ignored => {
            Ok(Json(rest_site_legacy_ok_response()))
        }
        persistence::SiteUserAvatarFromAttachmentResult::AttachmentNotFound => {
            Err(RestRouteError::not_found("attachment not found"))
        }
        persistence::SiteUserAvatarFromAttachmentResult::UserNotFound => {
            Err(RestRouteError::not_found("user not found"))
        }
    }
}

