async fn legacy_project_create_labels(
    headers: HeaderMap,
    owner: String,
    project_name: String,
    body: serde_json::Value,
    session_manager: SessionManager,
    backend: PilotBackend,
) -> Response {
    let Some(labels) = legacy_json_find_value(&body, "labels").and_then(|value| value.as_array())
    else {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({
                "message": "No issues key exists or value wasn't array!",
            })),
        )
            .into_response();
    };
    let PilotBackend::Repository(repository) = &backend else {
        return RestRouteError::not_implemented("project labels require repository backend")
            .into_response();
    };
    let actor_id =
        match legacy_external_authenticated_user_id(&headers, &session_manager, repository, true)
            .await
        {
            Ok(user_id) => user_id,
            Err(error) => return legacy_external_api_auth_error_response(error),
        };
    let authorization =
        match require_project_read(repository, &owner, &project_name, Some(actor_id)).await {
            Ok(authorization) => authorization,
            Err(error) => return RestRouteError::from_connect_error(error).into_response(),
        };
    let can_update = match project_update_allowed(&authorization) {
        Ok(can_update) => can_update,
        Err(error) => return RestRouteError::from_connect_error(error).into_response(),
    };
    if !can_update {
        return RestRouteError::from_connect_error(ConnectError::permission_denied(
            "issue label create is not allowed",
        ))
        .into_response();
    }

    let mut results = Vec::new();
    for label in labels {
        let Some(label) = legacy_project_label_body_from_value(label) else {
            return RestRouteError::bad_request("invalid project label payload").into_response();
        };
        let color = match normalize_issue_label_color(&label.label_color) {
            Ok(color) => color,
            Err(error) => return RestRouteError::from_connect_error(error).into_response(),
        };
        let create_result = match repository
            .create_project_label(persistence::CreateProjectLabelInput {
                category_is_exclusive: label.is_exclusive.is_some(),
                category_name: label.category_name.trim().to_string(),
                label_color: color,
                label_name: label.label_name.trim().to_string(),
                owner_name: owner.clone(),
                project_name: project_name.clone(),
            })
            .await
        {
            Ok(Some(result)) => result,
            Ok(None) => return RestRouteError::not_found("project not found").into_response(),
            Err(error) => return RestRouteError::internal(error.to_string()).into_response(),
        };
        let (created_label, created) = create_result;
        if created {
            results.push(serde_json::json!({
                "status": 201,
                "label": created_label.name,
                "category": created_label.category_name,
                "labelColor": created_label.color,
                "isExclusive": created_label.category_is_exclusive,
            }));
        } else {
            results.push(serde_json::json!({
                "status": 409,
                "reason": "Conflict",
                "message": "Failed to create a new label. The label may already exist.",
                "user": label.original,
            }));
        }
    }

    (StatusCode::CREATED, Json(results)).into_response()
}

#[derive(Clone, Debug)]
struct LegacyProjectLabelCreateItem {
    category_name: String,
    is_exclusive: Option<bool>,
    label_color: String,
    label_name: String,
    original: serde_json::Value,
}

fn legacy_project_label_body_from_value(
    value: &serde_json::Value,
) -> Option<LegacyProjectLabelCreateItem> {
    let category_name = legacy_json_find_value(value, "category")?
        .as_str()?
        .to_string();
    let label_color = legacy_json_find_value(value, "labelColor")?
        .as_str()?
        .to_string();
    let label_name = legacy_json_find_value(value, "labelName")?
        .as_str()?
        .to_string();
    let is_exclusive = legacy_json_find_value(value, "isExclusive")
        .filter(|value| value.is_boolean())
        .and_then(|value| value.as_bool());

    Some(LegacyProjectLabelCreateItem {
        category_name,
        is_exclusive,
        label_color,
        label_name,
        original: value.clone(),
    })
}

#[derive(Clone, Debug)]
struct DirectTranslationRequest {
    owner: String,
    project_name: String,
    resource_type: String,
    number: i64,
}

fn direct_translation_request_from_value(value: &serde_json::Value) -> DirectTranslationRequest {
    DirectTranslationRequest {
        owner: legacy_json_find_value(value, "owner")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string(),
        project_name: legacy_json_find_value(value, "projectName")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string(),
        resource_type: legacy_json_find_value(value, "type")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string(),
        number: legacy_json_find_value(value, "number")
            .and_then(|value| {
                value
                    .as_i64()
                    .or_else(|| value.as_str()?.trim().parse::<i64>().ok())
            })
            .unwrap_or_default(),
    }
}

async fn legacy_external_translation(
    headers: HeaderMap,
    body: serde_json::Value,
    session_manager: SessionManager,
    backend: PilotBackend,
    translation_proxy: TranslationProxyConfig,
) -> Response {
    if translation_proxy.api_url.trim().is_empty() {
        return direct_plain_response(StatusCode::PRECONDITION_FAILED, "Precondition Failed");
    }

    let PilotBackend::Repository(repository) = &backend else {
        return RestRouteError::not_implemented("translation requires repository backend")
            .into_response();
    };
    let actor_id =
        match legacy_external_authenticated_user_id(&headers, &session_manager, repository, true)
            .await
        {
            Ok(user_id) => user_id,
            Err(error) => return legacy_external_api_auth_error_response(error),
        };
    let body = direct_translation_request_from_value(&body);

    let text = match legacy_translation_source(repository, &body, actor_id).await {
        Ok(text) => text,
        Err(error) => return RestRouteError::from_connect_error(error).into_response(),
    };
    let translated = match legacy_translate_text(&translation_proxy, &text) {
        Ok(translated) => translated,
        Err(error) => return RestRouteError::bad_request(error).into_response(),
    };

    Json(serde_json::json!({
        "translated": translated,
        "translatedMarkdown": translated,
    }))
    .into_response()
}

async fn legacy_translation_source(
    repository: &PilotRepository,
    body: &DirectTranslationRequest,
    actor_id: i64,
) -> Result<String, ConnectError> {
    match body.resource_type.as_str() {
        "issue" => {
            let access = read_issue_access(
                repository,
                &body.owner,
                &body.project_name,
                body.number,
                Some(actor_id),
            )
            .await?;
            Ok(format!(
                "Title: {}\n\n{}",
                access.issue.title, access.issue.body_markdown
            ))
        }
        "posting" => {
            let access = read_posting_access(
                repository,
                &body.owner,
                &body.project_name,
                body.number,
                Some(actor_id),
            )
            .await?;
            Ok(format!(
                "Title: {}\n\n{}",
                access.posting.title, access.posting.body_markdown
            ))
        }
        "issue-comment" => {
            let origin = repository
                .read_issue_comment_origin(body.number)
                .await
                .map_err(internal_error)?
                .ok_or_else(|| ConnectError::not_found("issue comment not found"))?;
            read_issue_access(
                repository,
                &origin.owner_name,
                &origin.project_name,
                origin.issue_number,
                Some(actor_id),
            )
            .await?;
            Ok(origin.contents_markdown)
        }
        "post-comment" => {
            let origin = repository
                .read_posting_comment_origin(body.number)
                .await
                .map_err(internal_error)?
                .ok_or_else(|| ConnectError::not_found("posting comment not found"))?;
            read_posting_access(
                repository,
                &origin.owner_name,
                &origin.project_name,
                origin.post_number,
                Some(actor_id),
            )
            .await?;
            Ok(origin.contents_markdown)
        }
        _ => Err(ConnectError::invalid_argument(
            "translation resource type is invalid",
        )),
    }
}

fn legacy_translate_text(config: &TranslationProxyConfig, text: &str) -> Result<String, String> {
    if text.trim().is_empty() {
        return Ok(String::new());
    }
    let mut command = Command::new("curl");
    command
        .arg("-sS")
        .arg("-X")
        .arg("POST")
        .arg("-H")
        .arg("Accept: application/json,application/x-www-form-urlencoded,text/html,*/*")
        .arg("-H")
        .arg("Content-Type: application/x-www-form-urlencoded; charset=UTF-8");
    if !config.header_key.trim().is_empty() {
        command.arg("-H").arg(format!(
            "{}: {}",
            config.header_key.trim(),
            config.header_value
        ));
    }
    let output = command
        .arg("--data-urlencode")
        .arg("source=ko")
        .arg("--data-urlencode")
        .arg("target=en")
        .arg("--data-urlencode")
        .arg(format!("text={text}"))
        .arg(config.api_url.trim())
        .output()
        .map_err(|error| format!("translation.fetch.failed: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "translation.fetch.failed: exit status {}",
            output.status
        ));
    }
    let payload: serde_json::Value = serde_json::from_slice(&output.stdout)
        .map_err(|error| format!("translation.response.invalid: {error}"))?;
    payload
        .pointer("/result/translatedText")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .ok_or_else(|| "translation.response.missingTranslatedText".to_string())
}

async fn rest_read_code_browser(
    headers: HeaderMap,
    owner_name: String,
    project_name: String,
    query: RestCodeBrowserQuery,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
) -> Result<Json<RestCodeBrowserResponse>, RestRouteError> {
    let actor_id = session_manager
        .read_session_from_headers(&headers)
        .and_then(|session| session.user_id);
    let PilotBackend::Repository(repository) = &backend else {
        return Err(RestRouteError::from_connect_error(
            ConnectError::unimplemented("code browser requires repository backend"),
        ));
    };
    let authorization = repository
        .read_project_authorization(&owner_name, &project_name, actor_id)
        .await
        .map_err(internal_error)
        .map_err(RestRouteError::from_connect_error)?
        .ok_or_else(|| {
            RestRouteError::from_connect_error(ConnectError::not_found("project not found"))
        })?;
    if !project_read_allowed(&authorization, actor_id.is_none())
        .map_err(RestRouteError::from_connect_error)?
        || !project_code_menu_visible(&authorization, true)
    {
        return if actor_id.is_none() {
            Err(RestRouteError::from_connect_error(
                ConnectError::unauthenticated("project read is not allowed"),
            ))
        } else {
            Err(RestRouteError::from_connect_error(
                ConnectError::permission_denied("project read is not allowed"),
            ))
        };
    }

    let repo_path = yona_rust_vcs::repository_path(&yona_data_root(), authorization.project.id);
    let snapshot = yona_rust_vcs::read_code_browser(
        &repo_path,
        Some(query.branch.as_str()).filter(|value| !value.trim().is_empty()),
        &query.path,
    )
    .map_err(code_browser_error)
    .map_err(RestRouteError::from_connect_error)?;

    let mut response = code_browser_rest_response_from_snapshot(
        &authorization.project.owner_name,
        &authorization.project.project_name,
        snapshot,
        &base_path,
    );
    for entry in &mut response.entries {
        if entry.author_email.trim().is_empty() {
            continue;
        }
        let Some(author) = repository
            .find_user_by_identifier(&entry.author_email)
            .await
            .map_err(internal_error)
            .map_err(RestRouteError::from_connect_error)?
        else {
            continue;
        };
        entry.author_login_id = author.login_id.clone();
        entry.author_avatar_url =
            workspace_avatar_url(repository, author.id, &author.email_address, &base_path)
                .await
                .map_err(RestRouteError::from_connect_error)?;
    }
    if let Some(file) = response.file.as_mut() {
        if !file.author_email.trim().is_empty() {
            if let Some(author) = repository
                .find_user_by_identifier(&file.author_email)
                .await
                .map_err(internal_error)
                .map_err(RestRouteError::from_connect_error)?
            {
                file.author_login_id = author.login_id.clone();
                file.author_avatar_url =
                    workspace_avatar_url(repository, author.id, &author.email_address, &base_path)
                        .await
                        .map_err(RestRouteError::from_connect_error)?;
            }
        }
        if !file.commit_id.trim().is_empty() {
            let comment_counts = repository
                .count_commit_discussion_threads_by_commit(
                    authorization.project.id,
                    &[file.commit_id.clone()],
                    Some(&file.path),
                )
                .await
                .map_err(internal_error)
                .map_err(RestRouteError::from_connect_error)?;
            file.comment_count = *comment_counts.get(&file.commit_id).unwrap_or(&0);
        }
        if !file.is_binary
            && !file.is_too_large
            && (code_path_is_markdown(&file.path) || code_path_is_markdown(&file.name))
        {
            let markdown = file.text.clone();
            file.mention_references = markdown_mention_references(repository, &[markdown.as_str()])
                .await
                .map_err(RestRouteError::from_connect_error)?
                .iter()
                .map(rest_mention_reference_metadata_from_resolved)
                .collect();
        }
    }

    Ok(Json(response))
}

