fn code_file_to_rest(
    file: CodeFileRecord,
    base_path: &str,
    owner_name: &str,
    project_name: &str,
    branch: &str,
) -> RestCodeFile {
    let (html, text) = if code_file_record_is_renderable_markdown(&file) {
        (
            String::new(),
            rewrite_code_browser_markdown_image_links(
                &file.text,
                base_path,
                owner_name,
                project_name,
                branch,
            ),
        )
    } else {
        (String::new(), file.text)
    };
    RestCodeFile {
        author_avatar_url: String::new(),
        author_email: file.author_email,
        author_label: file.author_label,
        author_login_id: String::new(),
        commit_date: file.commit_date,
        commit_id: file.commit_id,
        comment_count: 0,
        commit_message: file.commit_message,
        commit_short_id: file.commit_short_id,
        html,
        is_binary: file.is_binary,
        is_too_large: file.is_too_large,
        mime_type: file.mime_type,
        mention_references: Vec::new(),
        name: file.name,
        path: file.path,
        size: file.size,
        text,
    }
}

fn project_readme_file_from_git(
    repo_path: &StdPath,
    base_path: &str,
    owner_name: &str,
    project_name: &str,
) -> Result<Option<RestProjectReadmeFile>, ConnectError> {
    for candidate in [
        "README.md",
        "readme.md",
        "README.markdown",
        "readme.markdown",
    ] {
        match yona_rust_vcs::read_code_browser(repo_path, None, candidate) {
            Ok(snapshot) => {
                let Some(file) = snapshot.file else {
                    continue;
                };
                if !code_file_record_is_renderable_markdown(&file) {
                    continue;
                }
                let body_markdown = rewrite_project_readme_markdown_links(
                    &file.text,
                    base_path,
                    owner_name,
                    project_name,
                    &snapshot.selected_branch,
                );
                return Ok(Some(RestProjectReadmeFile {
                    body_html: String::new(),
                    body_markdown,
                    mention_references: Vec::new(),
                    name: file.name,
                }));
            }
            Err(VcsError::NotFound) => continue,
            Err(error) => return Err(code_browser_error(error)),
        }
    }

    Ok(None)
}

fn code_file_record_is_renderable_markdown(file: &CodeFileRecord) -> bool {
    !file.is_binary && !file.is_too_large && code_path_is_markdown(&file.path)
}

fn code_path_is_markdown(path: &str) -> bool {
    let extension = path
        .rsplit_once('.')
        .map(|(_, extension)| extension.to_ascii_lowercase())
        .unwrap_or_default();
    matches!(
        extension.as_str(),
        "markdown" | "mdown" | "mkdn" | "mkd" | "md" | "mdwn"
    )
}

